def clip_above(points,height):
 result=[]
 for start,end in zip(points,np.roll(points,-1,axis=0)):
  inside_start=start[2]>height;inside_end=end[2]>height
  if inside_start: result.append(start)
  if inside_start!=inside_end:result.append(start+(end-start)*(height-start[2])/(end[2]-start[2]))
 return np.array(result)
